const cb = document.querySelector('input[type="checkbox"]');
if (cb) {
  // Simulate a real user click with mouse events
  const rect = cb.getBoundingClientRect();
  const x = rect.left + rect.width / 2;
  const y = rect.top + rect.height / 2;

  cb.dispatchEvent(new MouseEvent('mousedown', {clientX: x, clientY: y, bubbles: true}));
  cb.dispatchEvent(new MouseEvent('mouseup', {clientX: x, clientY: y, bubbles: true}));
  cb.dispatchEvent(new MouseEvent('click', {clientX: x, clientY: y, bubbles: true}));
  cb.click();

  return {found: true, checked: cb.checked, ariaLabel: cb.getAttribute('aria-label')};
}
return {found: false};
